-- Inspected production schema subset, 2026-10-04; isolated PostgreSQL test fixture only.
create role anon; create role authenticated; create role service_role bypassrls;
create schema auth; grant usage on schema auth to authenticated; create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create table public.wearable_health_imports(
  id uuid default gen_random_uuid() not null,
  user_id uuid not null,
  connection_id uuid,
  provider text default 'garmin'::text not null,
  provider_mode text default 'assisted_capture'::text not null,
  ingestion_channel text not null,
  health_record_type text not null,
  observation_date date not null,
  captured_at timestamptz default now() not null,
  source_reference text,
  source_asset_metadata jsonb default '{}'::jsonb not null,
  raw_observation jsonb default '{}'::jsonb not null,
  normalized_payload jsonb default '{}'::jsonb not null,
  data_confidence text default 'user_verified'::text not null,
  processing_status text default 'normalized'::text not null,
  readiness_snapshot_id uuid,
  notes text,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  raw_payload_id uuid,
  constraint wearable_health_imports_data_confidence_check CHECK ((data_confidence = ANY (ARRAY['reported'::text, 'user_verified'::text, 'calculated'::text, 'estimated'::text, 'ocr_unverified'::text, 'unknown'::text]))),
  constraint wearable_health_imports_health_record_type_check CHECK ((health_record_type = ANY (ARRAY['daily_summary'::text, 'sleep'::text, 'body_battery'::text, 'stress'::text, 'heart_rate'::text, 'hrv'::text, 'respiration'::text, 'weight'::text, 'pulse_ox'::text, 'composite'::text, 'other'::text]))),
  constraint wearable_health_imports_ingestion_channel_check CHECK ((ingestion_channel = ANY (ARRAY['chatgpt_assisted_capture'::text, 'lovable_manual_entry'::text, 'garmin_health_api'::text, 'admin_backfill'::text, 'mock_test'::text]))),
  constraint wearable_health_imports_pkey PRIMARY KEY (id),
  constraint wearable_health_imports_processing_status_check CHECK ((processing_status = ANY (ARRAY['received'::text, 'normalized'::text, 'linked'::text, 'error'::text, 'superseded'::text]))),
  constraint wearable_health_imports_provider_mode_check CHECK ((provider_mode = ANY (ARRAY['assisted_capture'::text, 'official_api'::text, 'manual_entry'::text, 'mock_test'::text]))));
alter table public.wearable_health_imports enable row level security;
create policy fixture_owner_select on public.wearable_health_imports for select to authenticated using ((select auth.uid())=user_id);
grant all on public.wearable_health_imports to authenticated;
grant truncate,references,trigger on public.wearable_health_imports to anon;
