CREATE UNIQUE INDEX wearable_health_imports_capture_reference_unique ON public.wearable_health_imports USING btree (user_id, ingestion_channel, source_reference, health_record_type) WHERE ((source_reference IS NOT NULL) AND (ingestion_channel = 'chatgpt_assisted_capture'::text));
CREATE UNIQUE INDEX wearable_hrv_nightly_summary_source_unique ON public.wearable_hrv_nightly_summaries USING btree (user_id, provider, ingestion_channel, calendar_date);
CREATE UNIQUE INDEX wearable_hrv_summary_source_unique ON public.wearable_hrv_nightly_summaries USING btree (user_id, provider, ingestion_channel, calendar_date);
