CREATE UNIQUE INDEX wearable_provider_raw_payload_official_hash_unique ON public.wearable_provider_raw_payloads USING btree (user_id, provider, ingestion_channel, api_product, payload_type, payload_sha256) WHERE ((external_payload_id IS NULL) AND (payload_sha256 IS NOT NULL) AND (ingestion_channel = 'garmin_health_api'::text));
CREATE UNIQUE INDEX wearable_sleep_sessions_source_unique ON public.wearable_sleep_sessions USING btree (user_id, provider, ingestion_channel, calendar_date);
CREATE UNIQUE INDEX wearable_vendor_insights_capture_unique ON public.wearable_vendor_insights USING btree (user_id, provider, ingestion_channel, observation_date, insight_code) WHERE (ingestion_channel = 'chatgpt_assisted_capture'::text);

